patches.proof_note:
We proceed in steps analogous to Proposition~\ref{prop:resid}.
\begin{enumerate}
    \item Markov inequality implies
     \begin{align*}
        \text{pr}(|\Delta_{4\ell}|>t_4)&\leq \frac{E(|\Delta_{4\ell}|)}{t_4};\\
        \text{pr}(|\Delta_{5\ell}|>t_5)&\leq \frac{E(|\Delta_{5\ell}|)}{t_5}; \\
        \text{pr}(|\Delta_{6\ell}|>t_6)&\leq \frac{E(|\Delta_{6\ell}|)}{t_6}.
    \end{align*}
    \item Law of iterated expectations implies
    \begin{align*}
        E(|\Delta_{4\ell}|)&=E\{E(|\Delta_{4\ell}|\mid I^c_{\ell})\};\\
        E(|\Delta_{5\ell}|)&=E\{E(|\Delta_{5\ell}|\mid I^c_{\ell})\}; \\
        E(|\Delta_{6\ell}|)&=E\{E(|\Delta_{6\ell}|\mid I^c_{\ell})\}.
    \end{align*}
    \item Bounding conditional moments.

     Conditional on $I_{\ell}^c$, $(u,v)$ are nonrandom. Moreover, observations within fold $I_{\ell}$ are independent and identically distributed. Conditional on $I_\ell^c$, $u=\hat\gamma_\ell-\gamma_0$ is fixed and belongs to $\Gamma$ by ass:patch-fitted-errors-in-gamma. Assumption~\ref{assumption:cont} gives $E(\Delta_{4\ell}\mid I_\ell^c)=E\{m(W,u)^2\mid I_\ell^c\}\leq\bar Q\{E[u(W)^2\mid I_\ell^c]\}^q=\bar Q\mathcal R(\hat\gamma_\ell)^q$.
   $$
   Similarly
    $$
       E(|\Delta_{5\ell}|\mid I^c_{\ell})= E(\Delta_{5\ell}\mid I^c_{\ell})
        =E[\{\hat{\alpha}_{\ell}(W)u(W)\}^2\mid I^c_{\ell}]
        \leq  (\bar{\alpha}')^2 \mathcal{R}(\hat{\gamma}_{\ell}).
   $$ Finally, with $v=\hat\alpha_\ell-\alpha_0^{\min}$ fixed given training data, iterated expectation and ass:patch-resid2-conditional-second-moment give $E(\Delta_{6\ell}\mid I_\ell^c)=E[v(W)^2E\{(Y-\gamma_0(W))^2\mid W\}\mid I_\ell^c]\leq\bar\sigma^2E[v(W)^2\mid I_\ell^c]=\bar\sigma^2\mathcal R(\hat\alpha_\ell)$. Conditional Markov inequality at each displayed threshold gives failure probability at most $\epsilon'/(6L)$; the union bound over the three thresholds gives $\epsilon'/(2L)$.
    \end{align*}
    \item Collecting results gives
     \begin{align*}
        \text{pr}(|\Delta_{4\ell}|>t_4)&\leq \frac{\bar{Q} \mathcal{R}(\hat{\gamma}_{\ell})^q}{t_4}=\frac{\epsilon'}{6L}\\
        \text{pr}(|\Delta_{5\ell}|>t_5)&\leq \frac{(\bar{\alpha}')^2 \mathcal{R}(\hat{\gamma}_{\ell})}{t_5}=\frac{\epsilon'}{6L} \\
        \text{pr}(|\Delta_{6\ell}|>t_6)&\leq \frac{\bar{\sigma}^2 \mathcal{R}(\hat{\alpha}_{\ell})}{t_6}=\frac{\epsilon'}{6L}
    \end{align*}
    Therefore with probability $1-\epsilon'/(2L)$, the following inequalities hold:
\begin{align*}
    |\Delta_{4\ell}|&\leq t_4=\frac{6L}{\epsilon'}\bar{Q} \mathcal{R}(\hat{\gamma}_{\ell})^q;\\
    |\Delta_{5\ell}|&\leq t_5=\frac{6L}{\epsilon'}(\bar{\alpha}')^2 \mathcal{R}(\hat{\gamma}_{\ell});\\
    |\Delta_{6\ell}|&\leq t_6=\frac{6L}{\epsilon'}\bar{\sigma}^2 \mathcal{R}(\hat{\alpha}_{\ell}).
\end{align*}
\end{enumerate}

dfm.var_kurt_tex:
\begin{thm}{}
Assume that $Y(z)$ has finite kurtosis $\kappa_z$.
Under the null of equal variance,
$$
t_{kvar} \equiv \frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{   \sqrt{     \left (  \widehat{\kappa}_1 - 1 \right) / N_1  + \left( \widehat{\kappa}_0 - 1 \right) / N_0       }       }  
\stackrel{d}{\longrightarrow} \mathcal{N}(0, 1), 
$$
as $N\rightarrow \infty$.
\label{thm::var-kurt}
\end{thm}

%\begin{proof}[Proof of Theorem \ref{cor::scale}.]
%Technical details omitted for space (but available upon request), but the core argument is that the CDFs formed by linearly interpolating the points of the discrete ECDFs can be transformed as above, and the resulting transformation gives a constant shift for the original point masses of the original distributions.
%\end{proof}

{\sc Proof.}
From the classic result \citep{lehmann1999elements}, we have
$$
\sqrt{N_t} (\widehat{\sigma}_t^2 - \sigma_t^2) \stackrel{d}{\longrightarrow} 
\mathcal{N} \left\{ 0,  \text{var}(Y_t - \mu_t)^2 = \sigma^4 (  \kappa_t - 1  )   \right\},
$$
and therefore using delta-method we have that
$$
\sqrt{N_t} (\log \widehat{\sigma}_t^2 - \log \sigma_t^2) \stackrel{d}{\longrightarrow} \mathcal{N}(0,    \kappa_t - 1     ).
$$
Under the null, $\sigma_1^2 = \sigma_0^2$, and $\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2$ has the following asymptotic distribution
\begin{equation}
\frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{  \sqrt{  (  \kappa_1 - 1  ) / N_1     + (\kappa_0 - 1 ) / N_0}    } 
\stackrel{d}{\longrightarrow} \mathcal{N}(0, 1).  \label{eq:asmp_var}
\end{equation}
Due to the fact that $\widehat{\kappa}_t\rightarrow \kappa_t$ in probability and Slutsky's Theorem, we have
$$
\frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{  \sqrt{   \left(  \widehat{ \kappa}_1 - 1 \right) / N_1     + \left(  \widehat{ \kappa}_0 - 1 \right) / N_0    }   } 
\stackrel{d}{\longrightarrow} \mathcal{N}(0, 1).\Box
$$

dfm.twoforms_tex:
\begin{lemma}{}
Take random variables $A$ and $B$ with invertible CDFs $F_A(\cdot)$ and $F_B(\cdot)$.  Then 
\[ F_A(y) = F_B(y - \tau) \qquad \forall y \in [F_A^{-1}(0),F_A^{-1}(1)]  \]
is equivalent to
\[ F_A^{-1}(p) - F_B^{-1}(p) = \tau \qquad \forall p \in [0,1] . \]\label{lemma::twoforms}
\end{lemma}
\bigskip
{\sc Proof of Lemma \ref{lemma::twoforms}.}
The conclusion follows if we couple $A$ and $B$ through a common Uniform$(0,1)$ random variable $U$: $A = F_A^{-1}(U)$ and $B = F_B^{-1}(U)$.
$\Box$

suggested_repair.corrected_statement:
Assume that $Y(z)$ has finite kurtosis $\kappa_z$. Suppose in addition that the potential-outcome pairs are independent draws from a common joint distribution with continuous, nondegenerate marginals, and that, independently of those draws, a complete randomization assigns exactly $N_1$ units to treatment and $N_0$ to control, with $N_1/N\rightarrow r\in(0,1)$. Under the null of equal variance,
$$
t_{kvar} \equiv \frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{\sqrt{(\widehat{\kappa}_1-1)/N_1+(\widehat{\kappa}_0-1)/N_0}}
\stackrel{d}{\longrightarrow}\mathcal{N}(0,1),
$$
as $N\rightarrow\infty$, where $t_{kvar}$ is defined to be $0$ if either sample variance or the displayed denominator is $0$. \label{thm::var-kurt}

suggested_repair.proof_note:
Under the independent sampling and complete randomization condition, conditional on the assignment the observations in arm $t$ are independent draws from $Y(t)$. Write $Q_t=(Y(t)-\mu_t)^2$. Since $E(Q_t)=\sigma_t^2$ and $\operatorname{var}(Q_t)=E\{(Y(t)-\mu_t)^4\}-\sigma_t^4=\sigma_t^4(\kappa_t-1)$, the finite fourth moment and the central limit theorem give $\sqrt{N_t}\{N_t^{-1}\sum Q_{ti}-\sigma_t^2\}\stackrel{d}{\longrightarrow}\mathcal{N}\{0,\sigma_t^4(\kappa_t-1)\}$. The difference between $\widehat{\sigma}_t^2$ and $N_t^{-1}\sum Q_{ti}$ is $O_P(N_t^{-1})$, because $\widehat{\\mu}_t-\mu_t=O_P(N_t^{-1/2})$; hence the same limit holds for $\widehat{\sigma}_t^2$. Since $\sigma_t^2>0$, the delta method, with derivative $1/\sigma_t^2$, yields $\sqrt{N_t}(\log\widehat{\sigma}_t^2-\log\sigma_t^2)\stackrel{d}{\longrightarrow}\mathcal{N}(0,\kappa_t-1)$.
Under the null, $\sigma_1^2 = \sigma_0^2$, and $\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2$ has the following asymptotic distribution
\begin{equation}
\frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{  \sqrt{  (  \kappa_1 - 1  ) / N_1     + (\kappa_0 - 1 ) / N_0}    } 
\stackrel{d}{\longrightarrow} \mathcal{N}(0, 1).  \label{eq:asmp_var}
\end{equation} Conditional on any assignment of the fixed group sizes, the two observed arm samples involve disjoint independent potential-outcome pairs, so the two log-variance limits are independent; their unconditional joint law is the same. Put $V_N=(\kappa_1-1)/N_1+(\kappa_0-1)/N_0$. Continuity and nondegeneracy imply $\kappa_t>1$: equality in $E(Q_t^2)\geq E(Q_t)^2$ would make $|Y(t)-\mu_t|$ constant almost surely. Thus $V_N>0$. Since $N_1/N\rightarrow r\in(0,1)$, both group sizes diverge and the independent weighted normal limits give $(\log\widehat{\sigma}_1^2-\log\widehat{\sigma}_0^2)/\sqrt{V_N}\stackrel{d}{\longrightarrow}\mathcal{N}(0,1)$ under $\sigma_1^2=\sigma_0^2$.
Due to the fact that $\widehat{\kappa}_t\rightarrow \kappa_t$ in probability and Slutsky's Theorem, we have
$$
\frac{\log \widehat{\sigma}_1^2 - \log \widehat{\sigma}_0^2}{  \sqrt{   \left(  \widehat{ \kappa}_1 - 1 \right) / N_1     + \left(  \widehat{ \kappa}_0 - 1 \right) / N_0    }   } 
\stackrel{d}{\longrightarrow} \mathcal{N}(0, 1).\Box
$$ The law of large numbers for the sample second and fourth central moments gives $\widehat{\kappa}_t\rightarrow\kappa_t$ in probability. Because $N_1/N$ has an interior limit and $\kappa_1+\kappa_0>2$, the ratio of the estimated denominator squared to $V_N$ converges in probability to $1$. Each sample variance is positive with probability tending to $1$, and the estimated denominator is positive with probability tending to $1$; assigning $t_{kvar}=0$ on the complementary event therefore does not change the limit.

